openaev-minio"}, "resources": [{"cloud_partition": "aws", "region": "eu-central-1", "data": {"details": "", "metadata": {"arn": "arn:aws:s3:::eu-west-staging-main-ff-oaev-openaev-minio", "name": "eu-west-staging-main-ff-oaev-openaev-minio", "owner_id": "5555b08a35bf5c3a054ef557dfbbd82844c169c9d42a1820c742097dc7b00995", "owner": null, "versioning": true, "logging": false, "public_access_block": {"block_public_acls": true, "ignore_public_acls": true, "block_public_policy": false, "restrict_public_buckets": false}, "acl_grantees": [{"display_name": null, "ID": "5555b08a35bf5c3a054ef557dfbbd82844c169c9d42a1820c742097dc7b00995", "type": "CanonicalUser", "URI": null, "permission": "FULL_CONTROL"}], "policy": {}, "encryption": "AES256", "region": "eu-central-1", "logging_target_bucket": null, "ownership": "BucketOwnerEnforced", "object_lock": false, "mfa_delete": false, "tags": [{"Key": "20260826032605", "Value": "20260826033116"}, {"Key": "20260827034223", "Value": "20260827034813"}, {"Key": "20260829033803", "Value": "20260829035202"}, {"Key": "20260830032804", "Value": "20260830034025"}, {"Key": "20260831032051", "Value": "20260831033008"}, {"Key": "20260828032804", "Value": "20260828033828"}, {"Key": "20260825034738", "Value": "20260825035832"}], "lifecycle": [], "replication_rules": [], "notification_config": {}, "object_sampling": null}}, "group": {"name": "s3"}, "labels": ["20260826032605:20260826033116", "20260827034223:20260827034813", "20260829033803:20260829035202", "20260830032804:20260830034025", "20260831032051:20260831033008", "20260828032804:20260828033828", "20260825034738:20260825035832"], "name": "eu-west-staging-main-ff-oaev-openaev-minio", "type": "AwsS3Bucket", "uid": "arn:aws:s3:::eu-west-staging-main-ff-oaev-openaev-minio"}], "category_name": "Findings", "category_uid": 2, "class_name": "Detection Finding", "class_uid": 2004, "cloud": {"account": {"name": "", "type": "AWS Account", "type_id": 10, "uid": "006621354852", "labels": []}, "org": {"name": "", "ou_uid": "", "ou_name": "", "uid": ""}, "provider": "aws", "region": "eu-central-1"}, "remediation": {"desc": "Enforce defense in depth: enable **S3 Block Public Access** at org/account and bucket levels (`BlockPublicAcls`, `IgnorePublicAcls`, `BlockPublicPolicy`, `RestrictPublicBuckets`). Apply **least privilege** with explicit principals; avoid ACLs via Object Ownership. Use private access patterns (e.g., CloudFront OAC or presigned URLs) and monitor with analyzers.", "references": ["https://hub.prowler.com/check/s3_bucket_public_access"]}, "risk_details": "Publicly accessible buckets jeopardize **confidentiality** through unauthenticated reads, **integrity** through write or ACL changes, and **availability** via object deletion or overwrite. Attackers can mass-exfiltrate data, host malware, or pivot after discovering secrets stored in objects.", "time": 1788199834, "time_dt": "2026-08-31T20:10:34.984528", "type_uid": 200401, "type_name": "Detection Finding: Create"}') ON CONFLICT (finding_id) DO NOTHING;
